private fun icon(name: String, filled: Boolean, path: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
        // shortcut: Compose 1.12.1's Skia stroke paint starts reading Round while Skia strokes mitred, and only a join
        // that differs from the one it reads is set; this empty Miter stroke makes the Round below reach Skia on iOS.
        // Drop it when SkiaBackedPaint's strokeJoin starts at Miter.
        .addPath(emptyList(), stroke = SolidColor(Color.Black), strokeLineJoin = StrokeJoin.Miter)
        .addPath(
            PathParser().parsePathString(path).toNodes(),
            fill = if (filled) SolidColor(Color.Black) else null,
            stroke = if (filled) null else SolidColor(Color.Black),
            strokeLineWidth = 2f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        ).build()
